pandas.lifted:
LOAD "train.csv" AS train;
FILL_NULL train.Age WITH MEDIAN;
FILL_NULL train.Embarked WITH MODE;
DROP train [Cabin, Ticket];
FILTER train WHERE Fare < 500;
EXPECT train.Age BETWEEN 0 AND 100;
SAVE train AS "train_lifted.csv";
